package got.wildlife; import got.GOTItems; import net.minecraft.world.damagesource.DamageSource; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.level.Level; public final class GOTBeaverEntity extends GOTDefensiveAnimalEntity { public GOTBeaverEntity(EntityType<? extends net.minecraft.world.entity.animal.Animal> t,Level l){super(t,l);xpReward=2;} public static AttributeSupplier.Builder createAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,20).add(Attributes.MOVEMENT_SPEED,.22).add(Attributes.ATTACK_DAMAGE,2).add(Attributes.FOLLOW_RANGE,16);} @Override public boolean canFreeze(){return false;} @Override protected void dropCustomDeathLoot(DamageSource s,int looting,boolean hit){super.dropCustomDeathLoot(s,looting,hit);spawnAtLocation(GOTItems.BEAVER_TAIL.get());for(int i=0;i<1+random.nextInt(2)+random.nextInt(looting+1);i++)spawnAtLocation(isOnFire()?GOTItems.BEAVER_COOKED.get():GOTItems.BEAVER_RAW.get());} }